package com.arxyt.territorycontrolcompat.network;
import com.arxyt.territorycontrolcompat.data.CompatSavedData; import net.minecraft.network.FriendlyByteBuf; import net.minecraft.server.level.ServerPlayer; import net.minecraftforge.network.NetworkEvent; import net.minecraftforge.network.PacketDistributor; import java.util.function.Supplier;
public record OpenCompatPacket(){public void encode(FriendlyByteBuf b){} public static OpenCompatPacket decode(FriendlyByteBuf b){return new OpenCompatPacket();} public static void handle(OpenCompatPacket p,Supplier<NetworkEvent.Context> s){s.get().enqueueWork(()->{ServerPlayer player=s.get().getSender();if(player!=null)CompatNetwork.CHANNEL.send(PacketDistributor.PLAYER.with(()->player),new CompatConfigPacket(CompatSavedData.get(player.serverLevel()).config(),true));});s.get().setPacketHandled(true);}}
